```javascript
// RedRoom Fitness - Shared JavaScript

document.addEventListener('DOMContentLoaded', function() {
  // Mobile menu toggle
  const mobileMenuBtn = document.getElementById('mobile-menu-btn');
  const mobileNav = document.getElementById('mobile-nav');
  if (mobileMenuBtn && mobileNav) {
    mobileMenuBtn.addEventListener('click', function() {
      mobileNav.classList.toggle('open');
    });
  }

  // Newsletter form validation
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(function(form) {
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      const input = form.querySelector('.newsletter-input');
      const message = form.querySelector('.newsletter-message');
      const email = input.value.trim();

      if (!email) {
        message.textContent = 'Please enter your email address.';
        message.className = 'newsletter-message error';
        input.classList.add('error');
        return;
      }

      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        message.textContent = 'Please enter a valid email address.';
        message.className = 'newsletter-message error';
        input.classList.add('error');
        return;
      }

      message.textContent = 'Welcome to the Red Room! Check your inbox for confirmation.';
      message.className = 'newsletter-message success';
      input.classList.remove('error');
      input.value = '';
    });
  });

  // FAQ Accordion (single-open)
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(function(item) {
    const question = item.querySelector('.faq-question');
    question.addEventListener('click', function() {
      const isOpen = item.classList.contains('open');
      // Close all
      faqItems.forEach(function(other) {
        other.classList.remove('open');
      });
      // Open clicked if it wasn't open
      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });

  // Floor/Treadmill Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  toggleBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      const target = btn.dataset.target;
      toggleBtns.forEach(function(b) { b.classList.remove('active'); });
      btn.classList.add('active');
      document.querySelectorAll('.toggle-content').forEach(function(content) {
        content.style.display = 'none';
      });
      const targetEl = document.getElementById(target);
      if (targetEl) {
        targetEl.style.display = 'block';
      }
    });
  });

  // Instructor Location Filter
  const locationFilter = document.getElementById('location-filter');
  if (locationFilter) {
    locationFilter.addEventListener('change', function() {
      const selected = this.value;
      const cards = document.querySelectorAll('.instructor-card');
      cards.forEach(function(card) {
        if (selected === 'all' || card.dataset.location === selected) {
          card.style.display = 'block';
        } else {
          card.style.display = 'none';
        }
      });
    });
  }

  // Carousel
  initCarousel();

  // Country selector
  const countrySelect = document.getElementById('country-select');
  // Just a visual element, no special behavior needed
});

function initCarousel() {
  const track = document.querySelector('.carousel-track');
  if (!track) return;

  const slides = track.querySelectorAll('.carousel-slide');
  const prevBtn = document.querySelector('.carousel-arrow.prev');
  const nextBtn = document.querySelector('.carousel-arrow.next');
  const dotsContainer = document.querySelector('.carousel-dots');

  let currentSlide = 0;
  const totalSlides = slides.length;

  // Create dots
  if (dotsContainer) {
    for (let i = 0; i < totalSlides; i++) {
      const dot = document.createElement('button');
      dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
      dot.addEventListener('click', function() {
        goToSlide(i);
      });
      dotsContainer.appendChild(dot);
    }
  }

  function goToSlide(index) {
    currentSlide = index;
    track.style.transform = 'translateX(-' + (currentSlide * 100) + '%)';
    updateDots();
  }

  function updateDots() {
    if (!dotsContainer) return;
    const dots = dotsContainer.querySelectorAll('.carousel-dot');
    dots.forEach(function(dot, i) {
      dot.classList.toggle('active', i === currentSlide);
    });
  }

  if (prevBtn) {
    prevBtn.addEventListener('click', function() {
      goToSlide(currentSlide === 0 ? totalSlides - 1 : currentSlide - 1);
    });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', function() {
      goToSlide(currentSlide === totalSlides - 1 ? 0 : currentSlide + 1);
    });
  }

  // Auto-play
  let autoPlay = setInterval(function() {
    goToSlide(currentSlide === totalSlides - 1 ? 0 : currentSlide + 1);
  }, 5000);

  // Pause on hover
  const container = document.querySelector('.carousel-container');
  if (container) {
    container.addEventListener('mouseenter', function() {
      clearInterval(autoPlay);
    });
    container.addEventListener('mouseleave', function() {
      autoPlay = setInterval(function() {
        goToSlide(currentSlide === totalSlides - 1 ? 0 : currentSlide + 1);
      }, 5000);
    });
  }

  // Touch/swipe support
  let touchStartX = 0;
  let touchEndX = 0;

  if (container) {
    container.addEventListener('touchstart', function(e) {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });

    container.addEventListener('touchend', function(e) {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        if (diff > 0) {
          goToSlide(currentSlide === totalSlides - 1 ? 0 : currentSlide + 1);
        } else {
          goToSlide(currentSlide === 0 ? totalSlides - 1 : currentSlide - 1);
        }
      }
    }, { passive: true });
  }
}
