/* RedRoom Fitness — Shared Styles */

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  background-color: #141414;
  color: #fff;
  font-family: 'Inter', sans-serif;
  overflow-x: hidden;
}

::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #141414; }
::-webkit-scrollbar-thumb { background: #FF0000; border-radius: 4px; }

/* ── Promo Bar ── */
.promo-bar {
  background: linear-gradient(90deg, #b30000, #FF0000, #b30000);
  padding: 10px 16px;
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  font-family: 'Oswald', sans-serif;
}
.promo-bar a { color: #fff; text-decoration: underline; margin-left: 8px; }

/* ── Navigation ── */
.main-nav {
  background: rgba(20,20,20,.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,0,0,.15);
  position: sticky; top: 0; z-index: 100;
}
.nav-link {
  color: #bbb;
  text-decoration: none;
  font-family: 'Oswald', sans-serif;
  font-size: 14px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: .08em;
  transition: color .2s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active { color: #FF0000; }
.util-link {
  font-size: 12px; font-weight: 600;
  border: 1px solid rgba(255,0,0,.45);
  padding: 6px 16px;
  border-radius: 2px;
}
.util-link:hover { background: #FF0000; color: #fff; border-color: #FF0000; }

/* ── Buttons ── */
.btn-primary {
  display: inline-block;
  background: #FF0000; color: #fff;
  font-family: 'Oswald', sans-serif;
  font-weight: 700; text-transform: uppercase; letter-spacing: .12em;
  padding: 16px 40px; font-size: 16px;
  border: 2px solid #FF0000; cursor: pointer;
  transition: all .3s; text-decoration: none;
}
.btn-primary:hover {
  background: #cc0000; border-color: #cc0000;
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(255,0,0,.45);
}
.btn-secondary {
  display: inline-block;
  background: transparent; color: #fff;
  font-family: 'Oswald', sans-serif;
  font-weight: 700; text-transform: uppercase; letter-spacing: .12em;
  padding: 16px 40px; font-size: 16px;
  border: 2px solid #fff; cursor: pointer;
  transition: all .3s; text-decoration: none;
}
.btn-secondary:hover {
  background: #fff; color: #141414;
  transform: translateY(-2px);
}

/* ── Section Helpers ── */
.section-heading {
  font-family: 'Oswald', sans-serif;
  font-weight: 700; text-transform: uppercase;
  letter-spacing: .04em; color: #fff;
}
.red-accent { color: #FF0000; }
.red-divider { width: 60px; height: 3px; background: #FF0000; border: none; }

/* ── Hero ── */
.hero-section {
  position: relative;
  min-height: 88vh;
  display: flex; align-items: center; justify-content: center;
  text-align: center; overflow: hidden;
}
.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(255,0,0,.18) 0%, transparent 65%),
    linear-gradient(180deg, #141414 0%, #1c0505 50%, #141414 100%);
}
.hero-lines {
  position: absolute; inset: 0; overflow: hidden; opacity: .12;
}
.hero-lines::before, .hero-lines::after {
  content: ''; position: absolute;
  width: 1px; height: 120vh;
  background: linear-gradient(180deg, transparent, #FF0000, transparent);
}
.hero-lines::before { left: 15%; top: -10vh; transform: rotate(8deg); }
.hero-lines::after  { right: 15%; top: -10vh; transform: rotate(-8deg); }

/* ── Toggle ── */
.toggle-container {
  display: inline-flex;
  background: #1a1a1a;
  border: 1px solid #2a2a2a;
  border-radius: 4px; overflow: hidden;
}
.toggle-btn {
  padding: 14px 40px;
  font-family: 'Oswald', sans-serif;
  font-weight: 600; text-transform: uppercase;
  letter-spacing: .1em; font-size: 16px;
  color: #888; cursor: pointer;
  border: none; background: transparent;
  transition: all .3s;
}
.toggle-btn.active { background: #FF0000; color: #fff; }

/* ── Schedule Table ── */
.schedule-table { width: 100%; border-collapse: collapse; }
.schedule-table th {
  font-family: 'Oswald', sans-serif;
  font-weight: 600; text-transform: uppercase;
  letter-spacing: .08em; font-size: 14px; color: #FF0000;
  padding: 16px 24px; text-align: left;
  border-bottom: 2px solid #FF0000; background: #1a1a1a;
}
.schedule-table td {
  padding: 14px 24px;
  border-bottom: 1px solid #2a2a2a;
  font-size: 15px; color: #ddd;
}
.schedule-table tr:hover td { background: rgba(255,0,0,.04); }

/* ── Instructor Card ── */
.instructor-card {
  background: #1a1a1a;
  border: 1px solid #2a2a2a;
  overflow: hidden; transition: all .3s;
}
.instructor-card:hover {
  border-color: #FF0000;
  transform: translateY(-6px);
  box-shadow: 0 12px 36px rgba(255,0,0,.12);
}
.instructor-photo {
  width: 100%; aspect-ratio: 1;
  display: flex; align-items: center; justify-content: center;
  font-size: 56px; color: rgba(255,0,0,.6);
  font-family: 'Oswald', sans-serif; font-weight: 700;
}
.instructor-info { padding: 20px 24px; }
.instructor-name {
  font-family: 'Oswald', sans-serif;
  font-weight: 600; font-size: 20px;
  text-transform: uppercase; letter-spacing: .04em; color: #fff;
}
.instructor-location {
  font-size: 13px; color: #FF0000;
  text-transform: uppercase; letter-spacing: .08em; margin-top: 4px;
}
.instructor-book {
  display: inline-block; margin-top: 14px;
  font-size: 13px; color: #fff; text-decoration: none;
  text-transform: uppercase; letter-spacing: .1em; font-weight: 600;
  font-family: 'Oswald', sans-serif;
  border-bottom: 1px solid #FF0000; padding-bottom: 2px;
  transition: all .2s;
}
.instructor-book:hover { color: #FF0000; }

/* ── FAQ Accordion ── */
.faq-item { border-bottom: 1px solid #2a2a2a; }
.faq-question {
  width: 100%;
  display: flex; justify-content: space-between; align-items: center;
  padding: 22px 0; background: none; border: none;
  color: #fff; font-family: 'Oswald', sans-serif;
  font-weight: 600; font-size: 20px;
  text-transform: uppercase; letter-spacing: .04em;
  cursor: pointer; text-align: left; transition: color .2s;
}
.faq-question:hover { color: #FF0000; }
.faq-icon {
  font-size: 28px; color: #FF0000;
  transition: transform .3s; flex-shrink: 0; margin-left: 16px;
  font-weight: 300;
}
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer {
  max-height: 0; overflow: hidden;
  transition: max-height .35s ease-out;
  color: #bbb; font-size: 15px; line-height: 1.7;
}
.faq-item.open .faq-answer { max-height: 300px; padding-bottom: 22px; }

/* ── Carousel ── */
.carousel-container { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  transition: transform .55s cubic-bezier(.25,.46,.45,.94);
}
.carousel-slide { min-width: 100%; position: relative; }
.carousel-slide-bg {
  width: 100%; height: 440px;
  display: flex; align-items: flex-end;
  padding: 32px 40px;
  position: relative;
}
.carousel-slide-bg::after {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(0deg, rgba(20,20,20,.85) 0%, transparent 50%);
}
.carousel-slide-label {
  position: relative; z-index: 2;
  font-family: 'Oswald', sans-serif;
  font-weight: 600; text-transform: uppercase;
  letter-spacing: .08em; font-size: 18px; color: #fff;
}
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 50px; height: 50px;
  background: rgba(255,0,0,.9); border: none; color: #fff;
  font-size: 22px; cursor: pointer; z-index: 10;
  display: flex; align-items: center; justify-content: center;
  transition: all .3s;
}
.carousel-arrow:hover { background: #FF0000; width: 58px; }
.carousel-arrow.prev { left: 0; }
.carousel-arrow.next { right: 0; }
.carousel-dots {
  display: flex; justify-content: center;
  gap: 10px; padding: 18px 0; background: #141414;
}
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: #2a2a2a; border: none; cursor: pointer;
  transition: all .3s;
}
.carousel-dot.active { background: #FF0000; transform: scale(1.4); }

/* ── Newsletter ── */
.newsletter-section {
  background: linear-gradient(180deg, #141414 0%, #1c0505 50%, #141414 100%);
}
.newsletter-form { display: flex; gap: 0; max-width: 520px; margin: 0 auto; }
.newsletter-input {
  flex: 1; padding: 16px 20px;
  background: #1a1a1a; border: 1px solid #2a2a2a; border-right: none;
  color: #fff; font-family: 'Inter', sans-serif; font-size: 14px; outline: none;
  transition: border-color .3s;
}
.newsletter-input:focus { border-color: #FF0000; }
.newsletter-input.error { border-color: #ff4444; }
.newsletter-btn {
  padding: 16px 32px; background: #FF0000; color: #fff;
  border: 1px solid #FF0000;
  font-family: 'Oswald', sans-serif; font-weight: 700;
  text-transform: uppercase; letter-spacing: .12em; font-size: 14px;
  cursor: pointer; transition: all .3s;
}
.newsletter-btn:hover { background: #cc0000; }
.newsletter-msg { margin-top: 10px; font-size: 13px; min-height: 20px; text-align: center; }
.newsletter-msg.success { color: #00cc66; }
.newsletter-msg.error { color: #ff4444; }

/* ── Footer ── */
.site-footer { background: #0a0a0a; border-top: 1px solid #222; }
.footer-heading {
  font-family: 'Oswald', sans-serif;
  font-weight: 600; text-transform: uppercase;
  letter-spacing: .1em; font-size: 14px; color: #FF0000;
  margin-bottom: 16px;
}
.footer-link {
  display: block; color: #888; text-decoration: none;
  font-size: 14px; padding: 4px 0; transition: color .2s;
}
.footer-link:hover { color: #fff; }
.country-select {
  background: #1a1a1a; border: 1px solid #2a2a2a;
  color: #fff; padding: 8px 14px; font-size: 13px;
  font-family: 'Inter', sans-serif; cursor: pointer; outline: none;
  border-radius: 2px;
}
.country-select:focus { border-color: #FF0000; }

/* ── Feature Card ── */
.feature-card {
  background: #1a1a1a; border: 1px solid #2a2a2a;
  padding: 40px 32px; text-align: center; transition: all .3s;
}
.feature-card:hover {
  border-color: rgba(255,0,0,.5);
  transform: translateY(-6px);
  box-shadow: 0 12px 36px rgba(255,0,0,.1);
}
.feature-icon {
  width: 68px; height: 68px; margin: 0 auto 22px;
  background: rgba(255,0,0,.08); border: 1px solid rgba(255,0,0,.25);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 30px; color: #FF0000;
}

/* ── Content Card ── */
.content-card {
  background: #1a1a1a; border: 1px solid #2a2a2a;
  padding: 36px; transition: all .3s;
}
.content-card:hover {
  border-color: rgba(255,0,0,.35);
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,.5);
}

/* ── Mobile Nav ── */
.mobile-menu-btn {
  display: none; background: none; border: none;
  color: #fff; font-size: 26px; cursor: pointer;
}
.mobile-nav { display: none; background: #141414; border-top: 1px solid #2a2a2a; padding: 16px 24px; }
.mobile-nav.open { display: block; }
.mobile-nav .nav-link { display: block; padding: 12px 0; border-bottom: 1px solid #222; }

/* ── Animations ── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 20px rgba(255,0,0,.2); }
  50%      { box-shadow: 0 0 40px rgba(255,0,0,.4); }
}
.pulse-glow { animation: pulseGlow 2.5s ease-in-out infinite; }

/* ── Responsive ── */
@media (max-width: 768px) {
  .mobile-menu-btn { display: block; }
  .desktop-nav { display: none !important; }
  .hero-section { min-height: 70vh; }
  .carousel-slide-bg { height: 300px; }
  .newsletter-form { flex-direction: column; }
  .newsletter-input { border-right: 1px solid #2a2a2a; }
  .toggle-btn { padding: 12px 24px; font-size: 14px; }
  .schedule-table th, .schedule-table td { padding: 10px 14px; font-size: 13px; }
}

